(243922, 15909, 1360, '<td valign="top">Great picture.  I don''t think it represents a real emotion, but it''s so beautiful, I can''t take that many points off. 6.</td>', 'Great picture.  I don''t think it represents a real emotion, but it''s so beautiful, I can''t take that many points off. 6.', '2003-03-24 00:13:58.000000', NULL, 1),
(243925, 15729, 1360, '<td valign="top">Great shot.  I almost submitted one like this, but i''m glad I didn''t.  Yours was better. 6.</td>', 'Great shot.  I almost submitted one like this, but i''m glad I didn''t.  Yours was better. 6.', '2003-03-24 00:14:54.000000', NULL, 1),
(243927, 15901, 1360, '<td valign="top">I''d like to have seen more detail, but considering how this shot was set up, more detaill, less contrast would be impossible.  still a nice shot. 5.</td>', 'I''d like to have seen more detail, but considering how this shot was set up, more detaill, less contrast would be impossible.  still a nice shot. 5.', '2003-03-24 00:16:27.000000', NULL, 1),
